def backfill():
    import uuid

    from app.care_domain import conversation_id

    connection = op.get_bind()
    rows = (
        connection.execute(
            sa.text(
                "SELECT patient_id,sender_id,recipient_id,min(created_at) AS created_at FROM care_messages GROUP BY patient_id,sender_id,recipient_id"
            )
        )
        .mappings()
        .all()
    )
    seen = set()
    for row in rows:
        first, second = sorted((row["sender_id"], row["recipient_id"]))
        cid = conversation_id(row["patient_id"], first, second)
        if cid not in seen:
            seen.add(cid)
            connection.execute(
                sa.text(
                    "INSERT INTO care_conversations(id,patient_id,first_user,second_user,created_by,status,sequence,created_at) VALUES (:id,:patient,:first,:second,:first,'active',0,:created)"
                ),
                {
                    "id": cid,
                    "patient": row["patient_id"],
                    "first": first,
                    "second": second,
                    "created": row["created_at"],
                },
            )
            for user in (first, second):
                grant = connection.execute(
                    sa.text(
                        "SELECT id FROM grants WHERE patient_id=:pid AND user_id=:user"
                    ),
                    {"pid": row["patient_id"], "user": user},
                ).scalar()
                if grant:
                    connection.execute(
                        sa.text(
                            "INSERT INTO care_participants(id,conversation_id,user_id,grant_id,joined_at,notifications) VALUES (:id,:cid,:user,:grant,:created,:notices)"
                        ),
                        {
                            "id": str(uuid.uuid4()),
                            "cid": cid,
                            "user": user,
                            "grant": grant,
                            "created": row["created_at"],
                            "notices": False,
                        },
                    )
        connection.execute(
            sa.text(
                "UPDATE care_messages SET conversation_id=:cid WHERE patient_id=:pid AND sender_id=:sender AND recipient_id=:recipient"
            ),
            {
                "cid": cid,
                "pid": row["patient_id"],
                "sender": row["sender_id"],
                "recipient": row["recipient_id"],
            },
        )


